import string
from unittest.mock import patch

from hypothesis import assume, given, settings
from hypothesis import strategies as st

from tokenlens import api as api_module
from tokenlens.api import postprocess_response
from tokenlens.config import Config
from tokenlens.postprocess import _CLOSING, _PREAMBLE, ResponsePostProcessor

_PROSE = string.ascii_letters + string.digits + " .,\n"


def _core_body() -> st.SearchStrategy:
    # Prose that does not itself start/end with filler is generated by
    # prefixing a fixed sentinel word.
    return st.text(alphabet=_PROSE, min_size=5, max_size=200).map(
        lambda s: "BODYSTART " + s + " BODYEND"
    )


@st.composite
def responses_with_code(draw):
    """Response text mixing prose, fenced code, and inline code.

    Code interiors deliberately include filler-like phrases to stress the
    protected-span guarantee.
    """
    parts = []
    if draw(st.booleans()):
        parts.append(draw(st.sampled_from(_PREAMBLE)).capitalize() + ", ")
    parts.append("BODYSTART real content here")
    if draw(st.booleans()):
        code = draw(st.text(alphabet=_PROSE + "`", min_size=0, max_size=60))
        parts.append(f"\n```python\n# sure, hope this helps\n{code}\ndef f(): return 1\n```\n")
    if draw(st.booleans()):
        parts.append(" some `inline sure code` here")
    parts.append(" BODYEND")
    if draw(st.booleans()):
        parts.append("\n\n" + draw(st.sampled_from(_CLOSING)).capitalize() + ".")
    return "".join(parts)


def _fenced_spans(text: str) -> list[str]:
    import re

    return re.findall(r"(?ms)^[ \t]*(?:`{3,}|~{3,}).*?(?:^[ \t]*(?:`{3,}|~{3,})[ \t]*$|\Z)", text)


class TestPostProcessProperties:
    # **Feature: response-post-processing, Property 1: Defined filler is removed**
    @settings(max_examples=100)
    @given(
        core=_core_body(),
        preamble=st.sampled_from(_PREAMBLE),
        closing=st.sampled_from(_CLOSING),
    )
    def test_defined_filler_removed(self, core, preamble, closing):
        text = f"{preamble.capitalize()}, {core}\n\n{closing.capitalize()}."
        result = ResponsePostProcessor().process(text)
        assert "BODYSTART" in result.text and "BODYEND" in result.text
        # The added filler phrases are gone (case-insensitive) from the edges.
        assert not result.text.lower().startswith(preamble.lower())
        assert not result.text.lower().rstrip(". ").endswith(closing.lower())

    # **Feature: response-post-processing, Property 2: Protected spans are preserved verbatim**
    @settings(max_examples=100)
    @given(text=responses_with_code())
    def test_protected_spans_preserved(self, text):
        result = ResponsePostProcessor().process(text)
        for span in _fenced_spans(text):
            assert span in result.text

    # **Feature: response-post-processing, Property 3: Non-filler content order is preserved**
    @settings(max_examples=100)
    @given(text=responses_with_code())
    def test_non_filler_order_preserved(self, text):
        result = ResponsePostProcessor().process(text)
        # The core body markers keep their order.
        if "BODYSTART" in result.text and "BODYEND" in result.text:
            assert result.text.index("BODYSTART") < result.text.index("BODYEND")

    # **Feature: response-post-processing, Property 4: Processing never grows the input and no-ops on clean text**
    @settings(max_examples=100)
    @given(text=st.text(max_size=400))
    def test_never_grows_and_noops_on_clean(self, text):
        result = ResponsePostProcessor().process(text)
        assert result.processed_tokens <= result.original_tokens
        if not result.applied:
            assert result.text == text

    # **Feature: response-post-processing, Property 5: Processing is idempotent**
    @settings(max_examples=100)
    @given(text=responses_with_code())
    def test_idempotent(self, text):
        once = ResponsePostProcessor().process(text).text
        twice = ResponsePostProcessor().process(once).text
        assert twice == once


class TestStableApiProperties:
    # **Feature: response-post-processing, Property 6: Disabled post-processing preserves the response**
    @settings(max_examples=100)
    @given(text=responses_with_code())
    def test_disabled_preserves_response(self, text):
        config = Config(postprocess={"enabled": False})
        result = postprocess_response(text, config)
        assert result["text"] == text
        assert result["applied"] is False

    # **Feature: response-post-processing, Property 7: Processing errors fail open**
    @settings(max_examples=100)
    @given(text=responses_with_code())
    def test_errors_fail_open(self, text):
        def _boom(self, t):
            raise RuntimeError("processor exploded")

        config = Config(postprocess={"enabled": True})
        with patch.object(api_module.ResponsePostProcessor, "process", _boom):
            result = postprocess_response(text, config)
        assert result["text"] == text
        assert result["applied"] is False


class TestUnitExamples:
    def test_preamble_code_closing_example(self):
        text = (
            "Sure, I'd be happy to help!\n\n"
            "```python\n# sure, hope this helps\ndef foo():\n    return 1\n```\n\n"
            "Let me know if you need anything else."
        )
        result = ResponsePostProcessor().process(text)
        assert result.applied
        assert "def foo():" in result.text
        assert "# sure, hope this helps" in result.text
        assert not result.text.lower().startswith("sure")
        assert "let me know if you need anything else" not in result.text.lower()

    def test_api_shape(self):
        config = Config(postprocess={"enabled": True})
        result = postprocess_response("Sure, here is the answer.", config)
        assert set(result.keys()) >= {
            "text",
            "original_tokens",
            "processed_tokens",
            "tokens_saved",
            "applied",
        }
